package com.shopsphere.util;

import com.shopsphere.config.AppConfig;

import java.io.IOException;
import java.io.InputStream;
import java.nio.file.Files;
import java.nio.file.Path;
import java.nio.file.StandardCopyOption;
import java.util.Locale;
import java.util.Set;
import java.util.logging.Logger;

/**
 * Stores uploaded product images outside the deployed web application.
 *
 * <p>Only a small set of image formats is accepted, the size is limited and the
 * stored file name is generated by the server, so an upload can never overwrite an
 * arbitrary file or escape the upload directory.
 */
public final class ImageStorage {

    private static final Logger LOG = Logger.getLogger(ImageStorage.class.getName());
    private static final long MAX_BYTES = 2L * 1024 * 1024;
    private static final Set<String> ALLOWED_EXTENSIONS = Set.of("png", "jpg", "jpeg", "gif", "webp");
    private static final Set<String> ALLOWED_CONTENT_TYPES = Set.of(
            "image/png", "image/jpeg", "image/gif", "image/webp");

    private ImageStorage() {
    }

    /** The directory that holds the uploaded images. */
    public static Path uploadDirectory() {
        String configured = System.getProperty("shopsphere.upload.dir");
        if (configured == null || configured.isBlank()) {
            configured = System.getenv("SHOPSPHERE_UPLOAD_DIR");
        }
        if (configured == null || configured.isBlank()) {
            configured = System.getProperty("java.io.tmpdir") + java.io.File.separator
                    + "shopsphere-uploads";
        }
        return Path.of(configured);
    }

    /**
     * Validates and stores an uploaded image.
     *
     * @param filename    the name of the uploaded file (only used for the extension)
     * @param contentType the content type reported by the browser
     * @param data        the file content
     * @return the relative URL of the stored image, e.g. {@code uploads/abc.png}
     * @throws IOException when the file is not acceptable or cannot be stored
     */
    public static String store(String filename, String contentType, InputStream data)
            throws IOException {
        String extension = extensionOf(filename);
        if (!ALLOWED_EXTENSIONS.contains(extension)) {
            throw new IOException("Only PNG, JPEG, GIF and WEBP images are allowed.");
        }
        String normalisedContentType = contentType == null ? "" : contentType.toLowerCase(Locale.ROOT);
        if (!normalisedContentType.isEmpty() && !ALLOWED_CONTENT_TYPES.contains(normalisedContentType)) {
            throw new IOException("The uploaded file is not a supported image.");
        }

        Path directory = uploadDirectory();
        Files.createDirectories(directory);

        String name = "img-" + PasswordHasher.randomToken(12) + "." + extension;
        Path target = directory.resolve(name).normalize();
        if (!target.startsWith(directory.normalize())) {
            throw new IOException("Invalid file name.");
        }

        byte[] content = data.readNBytes((int) MAX_BYTES + 1);
        if (content.length == 0) {
            throw new IOException("The uploaded file is empty.");
        }
        if (content.length > MAX_BYTES) {
            throw new IOException("The image is larger than 2 MB.");
        }
        if (!looksLikeImage(content, extension)) {
            throw new IOException("The uploaded file is not a valid image.");
        }
        Files.copy(new java.io.ByteArrayInputStream(content), target, StandardCopyOption.REPLACE_EXISTING);
        LOG.info("Stored uploaded image " + name);
        return "uploads/" + name;
    }

    /** Resolves a stored image name to a file, rejecting any path traversal. */
    public static Path resolve(String name) {
        if (name == null || name.isBlank()) {
            return null;
        }
        String fileName = name.startsWith("uploads/") ? name.substring("uploads/".length()) : name;
        Path directory = uploadDirectory().toAbsolutePath().normalize();
        Path candidate = directory.resolve(fileName).normalize();
        if (!candidate.startsWith(directory) || !Files.isRegularFile(candidate)) {
            return null;
        }
        return candidate;
    }

    private static String extensionOf(String filename) {
        if (filename == null) {
            return "";
        }
        int dot = filename.lastIndexOf('.');
        if (dot < 0 || dot == filename.length() - 1) {
            return "";
        }
        return filename.substring(dot + 1).toLowerCase(Locale.ROOT);
    }

    /** Checks the magic bytes so that a renamed executable cannot be stored. */
    private static boolean looksLikeImage(byte[] content, String extension) {
        if (content.length < 12) {
            return false;
        }
        return switch (extension) {
            case "png" -> (content[0] & 0xFF) == 0x89 && content[1] == 'P' && content[2] == 'N'
                    && content[3] == 'G';
            case "jpg", "jpeg" -> (content[0] & 0xFF) == 0xFF && (content[1] & 0xFF) == 0xD8;
            case "gif" -> content[0] == 'G' && content[1] == 'I' && content[2] == 'F';
            case "webp" -> content[0] == 'R' && content[1] == 'I' && content[2] == 'F' && content[3] == 'F'
                    && content[8] == 'W' && content[9] == 'E' && content[10] == 'B' && content[11] == 'P';
            default -> false;
        };
    }
}
